import React, { useEffect, useState } from 'react';
import { useLocation } from 'react-router-dom'; // Importar useLocation
import index from '../services/algolia'; // Asegúrate de que la ruta sea correcta

const MascotasCercanasPage = () => {
  const [mascotas, setMascotas] = useState([]);
  const location = useLocation(); // Obtener la ubicación actual

  // Obtener los parámetros de la URL
  const queryParams = new URLSearchParams(location.search);
  const latitude = queryParams.get('lat');
  const longitude = queryParams.get('lng');

  useEffect(() => {
    const fetchMascotasCercanas = async () => {
      try {
        // Obtener mascotas cercanas de Algolia
        const { hits } = await index.search('', {
          aroundLatLng: `${latitude},${longitude}`,
          aroundRadius: 500000, // 5 km de radio
        });

        // Obtener los IDs de las mascotas
        const petIds = hits.map(pet => pet.objectID);

        // Hacer una llamada a tu API SQL para obtener la información completa
        const response = await fetch(`http://localhost:3000/api/pets?ids=${petIds.join(',')}`);
        const data = await response.json();

        // Combinar la información de Algolia con la de SQL
        const mascotasConInfo = hits.map(hit => {
          const mascotaInfo = data.find(mascota => mascota.id === hit.objectID);
          return {
            ...hit,
            imageurl: mascotaInfo ? mascotaInfo.imageUrl : null, // Asigna la URL de la imagen
            descripcion: mascotaInfo ? mascotaInfo.descripcion : '', // Asigna la descripción
          };
        });

        setMascotas(mascotasConInfo);
      } catch (error) {
        console.error('Error buscando mascotas cercanas:', error);
      }
    };

    if (latitude && longitude) {
      fetchMascotasCercanas();
    }
  }, [latitude, longitude]);

  return (
    <div>
      <h1>Mascotas Cercanas</h1>
      {mascotas.length > 0 ? (
        <ul>
          {mascotas.map((pet) => (
            <li key={pet.objectID} style={{ marginBottom: '20px' }}>
              <div style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '10px', display: 'flex', alignItems: 'center' }}>
                <img 
                  src={pet.imageurl} // Ahora usamos la URL de SQL
                  alt={pet.name} 
                  style={{ width: '100px', borderRadius: '8px', marginRight: '10px' }} 
                  onError={(e) => { e.target.onerror = null; e.target.src = 'ruta/por/defecto.png'; }} // Cambia a una imagen por defecto si falla
                />
                <div>
                  <h2>{pet.name}</h2>
                  <p>{pet.descripcion}</p>
                  <button style={{ backgroundColor: '#ff4081', color: '#fff', border: 'none', borderRadius: '5px', padding: '5px 10px' }}>
                    Reportar
                  </button>
                </div>
              </div>
            </li>
          ))}
        </ul>
      ) : (
        <p>No se encontraron mascotas cercanas.</p>
      )}
    </div>
  );
};

export default MascotasCercanasPage;
